## From Code Review REC-1 + REC-5

### REC-1: Processor Health Check

Add self-test function to validate processor environment at startup.

```typescript
export async function healthCheck(): Promise<{ healthy: boolean; errors: string[] }> {
  const errors: string[] = [];

  // Validate logger works
  try {
    logger.debug('Processor health check: logger OK');
  } catch (err) {
    errors.push(\`Logger not available: \${err}\`);
  }

  // Validate all handlers are loadable
  for (const [jobType, handler] of Object.entries(jobHandlers)) {
    if (\!handler || typeof handler.process \!== 'function') {
      errors.push(\`Handler for \${jobType} is not callable\`);
    }
  }

  return { healthy: errors.length === 0, errors };
}

// Run at processor load
if (process.env.NODE_ENV \!== 'test') {
  healthCheck().then(result => {
    if (\!result.healthy) {
      logger.error({ errors: result.errors }, 'Processor health check failed');
      process.exit(1);
    }
    logger.info('Processor health check passed');
  });
}
```

### REC-5: Processor Timeout (TTL Pattern)

BullMQ pattern for sandboxed processor timeout:

```typescript
const MAX_TTL = parseInt(process.env.PROCESSOR_MAX_TTL_MS || '600000'); // 10 min default
const TTL_EXIT_CODE = 10;

export default async function (job: SandboxedJob<JobData>): Promise<JobResult> {
  let hasCompleted = false;

  const hardKillTimeout = setTimeout(() => {
    if (\!hasCompleted) {
      logger.error({ jobId: job.id }, 'Processor TTL exceeded, force killing');
      process.exit(TTL_EXIT_CODE);
    }
  }, MAX_TTL);

  try {
    const result = await processJob(job);
    hasCompleted = true;
    return result;
  } finally {
    clearTimeout(hardKillTimeout);
  }
}
```

